import {HEROES,currentNode} from './engine.js';
const ART='assets/illustrations3/',esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function titleChoices(saved){
 const active=!!saved&&saved.phase!=='title',start={action:'new',label:'원정 시작',hint:'새로운 서약을 시작합니다.',enabled:true},resume={action:'continue',label:'이어하기',hint:active?`${saved.party.map(id=>HEROES[id]?.name||'').filter(Boolean).join(' · ')} / ${currentNode(saved).name}`:'이어갈 원정 기록이 없습니다.',enabled:active},menu={action:'hub-menu',label:'메뉴',hint:'환경설정 · 도감',enabled:true};
 return active?[resume,start,menu]:[start,resume,menu];
}
export function titleScreen(saved,entered=false){
 const choices=titleChoices(saved),primary=choices.find(c=>c.enabled),embers=Array.from({length:18},(_,i)=>`<i style="--x:${9+(i*37)%83}%;--y:${62+(i*11)%35}%;--delay:${-(i*1.73)}s;--duration:${13+(i*7)%14}s;--drift:${-24+(i*13)%49}px;--size:${i%4===0?2:1}px"></i>`).join('');
 return `<section class="title-screen title-cinema" data-mode="${entered?'menu':'entry'}"><div class="title-scene" aria-hidden="true"><img class="title-background" src="${ART}title-main.webp" alt="" fetchpriority="high"><div class="title-atmosphere"></div><div class="title-mist mist-back"></div><div class="title-mist mist-front"></div><div class="title-embers">${embers}</div></div><div class="title-shading"></div><header class="title-brand"><p class="title-edition">TEYVAT DEFENSE</p><div class="title-logo-crop"><img src="${ART}title-logo.webp" alt="티바트 방어전 · 잔불" draggable="false" fetchpriority="high"></div><p class="title-tagline">꺼진 세계에, 아직 남아 있는 불빛.</p></header><button class="touch-start" data-action="enter-title" aria-label="Touch To Start" ${entered?'hidden':''}></button><div class="title-entry-prompt" aria-hidden="true"><span class="title-prompt-rule"></span><span class="title-prompt-label">TOUCH TO START<small>화면을 눌러 시작</small></span><span class="title-prompt-rule"></span></div><nav class="title-menu" aria-label="메인 메뉴" ${entered?'':'hidden'}><div class="title-menu-line"><span></span><i></i><span></span></div>${choices.map((c,i)=>`<button class="title-option ${c===primary?'title-primary':''}" data-action="${c.action}" data-title-hint="${esc(c.hint)}" ${c.enabled?'':'disabled'} style="--order:${i}"><span class="title-option-marker" aria-hidden="true"></span><span class="title-option-label">${c.label}</span><span class="title-option-marker" aria-hidden="true"></span></button>`).join('')}<p class="title-menu-caption">${esc(primary.hint)}</p></nav><footer class="title-colophon"><span>GENSHIN IMPACT FAN GAME</span><span>비공식 팬게임 · 개발판 0.34</span></footer><div class="title-letterbox" aria-hidden="true"></div></section>`;
}
export function revealTitleMenu(root){
 if(!root||root.dataset.mode==='menu')return;root.dataset.mode='menu';const entry=root.querySelector('.touch-start'),menu=root.querySelector('.title-menu');entry.hidden=true;menu.hidden=false;menu.querySelector('button:not(:disabled)')?.focus({preventScroll:true});
}
